const icons={Home:'<path d="m3 10 9-7 9 7v11h-6v-7H9v7H3Z"/>',FOND:'<path d="M4 8h12v9a4 4 0 0 1-4 4H8a4 4 0 0 1-4-4Z M16 9h2a3 3 0 0 1 0 6h-2 M7 2v3 M11 2v3"/>',Gym:'<path d="m6 4 14 14 M3 7l4-4 M2 12l10-10 M12 22l10-10 M17 21l4-4"/>',Padel:'<circle cx="12" cy="12" r="9"/><path d="M5 6q9 0 14 10 M6 19q0-10 12-14 M3 13q12 0 12 8"/>',Functions:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 2v6 M17 2v6 M3 11h18 M7 15h2 M12 15h2 M17 15h1"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.FOND}</svg>`;
function art(kind){let food=kind==='coffee'?'<ellipse cx="68" cy="105" rx="40" ry="8" fill="#d5c3a6"/><path d="M99 44h8c23 0 21 40-8 39" fill="none" stroke="#fdf9ed" stroke-width="10"/><path d="M30 36h70l-6 53q-28 20-56 0Z" fill="#faf6e9"/><ellipse cx="65" cy="37" rx="35" ry="11" fill="#ac7049"/><ellipse cx="65" cy="38" rx="25" ry="8" fill="#ead0a5"/><path d="M65 31q-20 1-10 8 10 8 20 0-1-7-10-8Z" fill="#fcf8e7"/>':kind==='bun'?'<ellipse cx="75" cy="102" rx="57" ry="10" fill="#d1bd97"/><path d="M20 51q55-70 110 0Z" fill="#c68c40"/><path d="M27 49q48-47 96 0" fill="#e7b765"/><path d="M22 63q28-14 51 0t54 0" fill="none" stroke="#658344" stroke-width="12"/><path d="M25 70h100" stroke="#a35335" stroke-width="10"/><ellipse cx="77" cy="68" rx="28" ry="12" fill="#fff7d7"/><ellipse cx="77" cy="68" rx="11" ry="9" fill="#e9ac37"/><path d="M20 84h110q-7 24-55 24T20 84" fill="#d99f4f"/>':'<ellipse cx="75" cy="74" rx="62" ry="35" fill="#dfd0b6"/><ellipse cx="75" cy="70" rx="55" ry="29" fill="#faf4e4"/><path d="m37 54 66-10 14 43-67 7Z" fill="#c48e49"/><path d="m43 57 55-8 11 34-54 6Z" fill="#88a052"/><path d="M49 66q16-19 29-6t18 16q-16 18-37 8Z" fill="#fcf8e8"/><ellipse cx="74" cy="70" rx="12" ry="10" fill="#e5b044"/><path d="m45 41 10-14 M59 45l10-20 M89 42l7-14" stroke="#667b4f" stroke-width="3"/><circle cx="101" cy="73" r="7" fill="#b96445"/>';
return `<div class="art"><svg viewBox="0 0 150 130" role="img" aria-label="Illustrative food artwork">${food}</svg></div>`}
const products=[{id:'avo',name:'Smashed Avo',desc:'Sourdough, smoked feta whip, carrot crisps and tahini drizzle.',cat:'Breakfast',price:120,kind:'toast'},{id:'bun',name:'Brekkie Bun',desc:'Brioche, crispy bacon, fried egg, chilli crisp and American mustard.',cat:'Breakfast',price:95,kind:'bun'},{id:'eggs',name:'Classic Eggs Benedict',desc:'Soft-poached eggs, hollandaise, sautéed spinach and toasted English muffin.',cat:'Breakfast',price:110,kind:'toast'},{id:'halloumi',name:'Honey Halloumi Bowl',desc:'Grilled halloumi, summer salad, hummus, poached eggs and pita crisps.',cat:'Bowls',price:100,kind:'toast'},{id:'bagel',name:'Chicken & Torched Brie Bagel',desc:'Pulled chicken, torched Brie, basil pesto and balsamic tomatoes.',cat:'Sandwiches',price:120,kind:'bun'},{id:'club',name:'FOND Club Sandwich',desc:'Pulled chicken, crispy bacon, tomato and garlic aioli. Served with chips.',cat:'Sandwiches',price:120,kind:'bun'},{id:'flat',name:'Flat White',desc:'Espresso with silky steamed milk. Your everyday coffee moment.',cat:'Coffee',price:35,kind:'coffee'},{id:'capp',name:'Cappuccino',desc:'Espresso, steamed milk and a soft layer of foam.',cat:'Coffee',price:35,kind:'coffee'},{id:'grill',name:'Rump Steak · 250g',desc:'Grilled to your liking, with your choice of side and sauce.',cat:'Grill',price:180,kind:'toast',sold:true}];
const categories=['All','Breakfast','Sandwiches','Bowls','Coffee','Grill'];let category='All',search='',mode='Collection',cart=[],selected,qty=1;const app=document.querySelector('#app');const money=v=>'R'+v.toFixed(2);
const row=(label,copy,href,kind='FOND')=>`<a class="action-row" href="#${href}">${icon(kind)}<div><b>${label}</b>${copy?`<small>${copy}</small>`:''}</div><span class="chevron">›</span></a>`;
function fond(){return `<div class="content"><p class="kicker">FOND / MIDPOINT</p><h1 class="heading">Good food.<br><em>Good days.</em></h1><p class="intro">Quality coffee, fresh food and all-day favourites. A little pause in the middle of everything.</p><a class="primary" href="#menu"><span>Order now</span><span>→</span></a><div class="meta"><b class="dot">● Sample trading status</b><b>Collection & delivery</b></div><div style="margin-top:18px">${row('Explore the menu','Find your next favourite.','menu')}${row('Order again','Your favourites, one tap away.','reorder')}${row('Delivery or collection','Choose what suits your day.','fulfilment','Home')}${row('Opening hours','See when to visit.','hours','Functions')}</div><a href="#rewards" class="reward" style="display:block"><div class="top"><b>Your coffee moments</b><span>→</span></div><p>7 of 10 coffees · sample rewards account</p><div class="stamps">${Array.from({length:10},(_,i)=>`<span class="${i<7?'filled':''}">${i<7?'✓':''}</span>`).join('')}</div></a><p class="sample">Illustrative preview. Prices, options, hours and rewards require confirmation against live settings.</p></div>`}
function product(p){return `<button class="product" data-product="${p.id}" ${p.sold?'disabled':''}><div>${p.sold?'<p class="kicker">SOLD OUT</p>':''}<h3>${p.name}</h3><p>${p.desc}</p><strong>${money(p.price)}</strong></div><div style="position:relative">${art(p.kind)}${!p.sold?'<span class="plus">+</span>':''}</div></button>`}
function menu(){return `<div class="menu-head"><div class="line"><h1>FOND menu</h1><a href="#fond">About FOND ↗</a></div><div class="mode">${['Collection','Delivery'].map(x=>`<button data-mode="${x}" class="${mode===x?'active':''}">${x}</button>`).join('')}</div><div class="location">${mode==='Collection'?'Collect at FOND · Midpoint Hub':'Deliver within Midpoint · choose your location at checkout'}</div><label class="search">⌕ <input id="search" type="search" placeholder="Find your favourite" aria-label="Search the menu" value="${search.replaceAll('&','&amp;').replaceAll('"','&quot;').replaceAll('<','&lt;')}"></label></div><div class="tabs" role="tablist" aria-label="Menu categories">${categories.map(c=>`<button role="tab" aria-selected="${category===c}" data-cat="${c}" class="${category===c?'active':''}">${c}</button>`).join('')}</div><div id="menu-results" class="content" style="padding-top:0">${results()}</div>`}
function results(){const list=products.filter(p=>(category==='All'||p.cat===category)&&`${p.name} ${p.desc}`.toLowerCase().includes(search.toLowerCase()));return `${category==='All'&&!search?`<div class="section-title"><h2>A few favourites</h2><span class="kicker" style="margin:0;font-size:8px">FOND PICKS</span></div><div class="highlights">${products.slice(0,2).concat(products[6]).map(p=>`<button class="highlight" data-product="${p.id}">${art(p.kind)}<b>${p.name}</b><small>${money(p.price)}</small></button>`).join('')}</div>`:''}<div class="section-title"><h2>${search?'Search results':category==='All'?'All-day favourites':category}</h2><span style="font-size:10px;color:#7a8077">${list.length} items</span></div>${list.map(product).join('')||'<p class="empty">No matches. Try another favourite.</p>'}${category==='All'&&!search?`<div class="section-title"><h2>Explore the menu</h2></div>${categories.slice(1).map(c=>`<button class="category-row" data-cat="${c}">${c}<span>›</span></button>`).join('')}`:''}<p class="sample">Illustrative artwork and sample selections. Live photography and current menu will be used in the final build.</p>`}
function home(){return `<div class="content"><p class="kicker">YOUR MIDPOINT</p><h1 class="heading">More to<br><em>your day.</em></h1><p class="intro">Eat. Move. Play. Get together.</p><img class="home-photo" src="assets/midpoint-hub-exterior.webp" alt="Midpoint Hub building"><div class="tiles">${[['fond','FOND','ORDER FOOD','fond-3'],['gym','GYM','MOVE YOUR WAY','gym-3'],['padel','PADEL','FIND YOUR GAME','padel-2'],['functions','FUNCTIONS','GET TOGETHER','fond-1'],['carwash','CAR WASH','COMING SOON','car-wash'],['suites','THE SUITES','COMING SOON','suites']].map(([id,title,copy,photo])=>`<a href="#${id}" class="tile"><img src="assets/tile-${photo}.webp" alt="">${['suites','carwash'].includes(id)?'<span class="coming">COMING SOON</span>':''}<div><b>${title}</b><small>${copy}</small></div></a>`).join('')}</div></div>`}
function destination(id){const info={gym:['MOVE / MIDPOINT','A stronger<br><em>every day.</em>','Make movement part of your routine. Your gym, your community, your pace.','gym-3','Explore memberships','Memberships, classes and upcoming events.'],padel:['PLAY / MIDPOINT','Find your<br><em>next game.</em>','A little competition. A lot of connection. Meet us on the court.','padel-2','Book a court','Court bookings, tenant signup and events.'],functions:['GATHER / MIDPOINT','Make it<br><em>an occasion.</em>','From working lunches to celebrations. Bring your people together at Midpoint.','fond-1','Plan your event','Spaces, menus and private gatherings.'],carwash:['COMING SOON','A fresh start.<br><em>For your car.</em>','Wash while you work. This destination is coming soon.','car-wash','Keep exploring',''],suites:['COMING SOON','Settle in.<br><em>Stay a while.</em>','Corporate accommodation at Midpoint. This destination is coming soon.','suites','Keep exploring','']}[id];return `<div class="content"><p class="kicker">${info[0]}</p><h1 class="heading">${info[1]}</h1><p class="intro">${info[2]}</p><a class="primary" href="#${['suites','carwash'].includes(id)?'home':id+'-details'}"><span>${info[4]}</span><span>→</span></a><img class="destination-photo" style="margin-top:23px" src="assets/tile-${info[3]}.webp" alt="${id} at Midpoint">${row('Explore '+(id==='gym'?'classes':id==='padel'?'events':'spaces'),info[5],id+'-details',id==='gym'?'Gym':id==='padel'?'Padel':'Functions')}${row('Back to Midpoint','Everything in one place.','home','Home')}<p class="sample">Landing page concept. This preview does not submit bookings or enquiries.</p></div>`}
function utility(id){const data={reorder:['Your favourites.<br><em>Again.</em>','An example of an earlier order.','Brekkie Bun + Flat White'],rewards:['A little<br><em>thank you.</em>','Sample rewards account: 7 of 10 coffees.','Three more coffees to your next reward.'],hours:['Make time<br><em>for FOND.</em>','Opening hours will use the current FOND trading settings.','Sample hours: Mon–Fri 06:30–18:00 · Sat 07:00–14:00'],fulfilment:['Your food.<br><em>Your way.</em>','Collect at FOND or choose delivery within Midpoint.','Select your preference on the menu.'],account:['Your Midpoint.<br><em>All together.</em>','Your orders, favourites and rewards in one place.','Account preview. No personal details collected.']}[id]||['More at<br><em>Midpoint.</em>','This destination has its own landing page and focused next steps.','Bookings and enquiries are shown as concepts only.'];return `<div class="content"><p class="kicker">MIDPOINT / PREVIEW</p><h1 class="heading">${data[0]}</h1><p class="intro">${data[1]}</p><div class="reward"><p>${data[2]}</p></div>${row('Explore the FOND menu','Find something you love.','menu')}${row('Home','Return to Midpoint.','home','Home')}</div>`}
function render(){let id=location.hash.slice(1)||'fond';app.innerHTML=id==='fond'?fond():id==='menu'?menu():id==='home'?home():['gym','padel','functions','carwash','suites'].includes(id)?destination(id):utility(id);app.scrollTop=0;document.querySelector('#nav').innerHTML=['Home','FOND','Gym','Padel','Functions'].map(n=>{const dest=n==='Home'?'home':n.toLowerCase();let active=id===dest||(n==='FOND'&&['menu','rewards','reorder','fulfilment','hours'].includes(id));return `<a href="#${dest}" ${active?'aria-current="page"':''}>${icon(n)}<span>${n}</span></a>`}).join('');updateBasket()}
function openItem(id){selected=products.find(p=>p.id===id);if(!selected||selected.sold)return;qty=1;const coffee=selected.kind==='coffee';document.querySelector('#item-content').innerHTML=`<form id="customise"><div class="modal-body"><button type="button" class="close" data-close="item" aria-label="Close item">×</button>${art(selected.kind)}<p class="kicker">FOND / ${selected.cat.toUpperCase()}</p><h2>${selected.name}</h2><p>${selected.desc}</p><p class="sample">Sample customisation options for design review.</p><fieldset><legend>${coffee?'Choose your milk':'Choose your preparation'}<span class="required">REQUIRED</span></legend>${(coffee?['Full cream','Low fat','Oat milk']:['House style','Vegetarian option']).map((v,i)=>`<label class="option"><input type="radio" name="choice" value="${v}" required ${i===0?'checked':''}>${v}<span>Included</span></label>`).join('')}</fieldset><fieldset><legend>Make it yours <span class="required">OPTIONAL</span></legend><label class="option"><input type="checkbox" id="extra">${coffee?'Extra espresso shot':'Add an extra egg'}<span>+ R12.00</span></label></fieldset><label for="instructions" style="font-size:12px">Special instructions</label><textarea id="instructions" placeholder="Anything we should know? (preview only)" maxlength="240"></textarea><div class="quantity"><b style="font-size:13px">Quantity</b><div style="display:flex;align-items:center;gap:20px"><button type="button" data-qty="-1" aria-label="Decrease quantity">−</button><b id="qty">1</b><button type="button" data-qty="1" aria-label="Increase quantity">+</button></div></div></div><div class="modal-footer"><button class="primary" type="submit"><span>Add to basket</span><span id="total" style="font-size:14px">${money(selected.price)}</span></button></div></form>`;document.querySelector('#item').showModal()}
const unit=()=>selected.price+(document.querySelector('#extra')?.checked?12:0);
function updateBasket(){const bar=document.querySelector('#basket-bar');bar.hidden=!cart.length;bar.innerHTML=cart.length?`<button data-basket><span>${cart.reduce((n,c)=>n+c.qty,0)} items · View basket</span><b>${money(cart.reduce((n,c)=>n+c.unit*c.qty,0))}</b></button>`:''}
function basket(){document.querySelector('#basket-content').innerHTML=`<div class="modal-body"><button class="close" data-close="basket" aria-label="Close basket">×</button><p class="kicker">FOND / SAMPLE ORDER</p><h2>Your basket.</h2>${cart.map((c,i)=>`<div class="action-row"><div><b>${c.qty} × ${c.name}</b><small>${c.choice}${c.extra?' · Extra added':''}</small></div><strong style="font-size:12px">${money(c.qty*c.unit)}</strong><button data-remove="${i}" aria-label="Remove ${c.name}" style="background:none;color:var(--wine)">×</button></div>`).join('')||'<p>Your basket is empty.</p>'}<div class="quantity"><b>Total</b><b>${money(cart.reduce((n,c)=>n+c.unit*c.qty,0))}</b></div><p class="sample">This is a design preview. Nothing has been ordered or paid. Delivery fees and checkout are not simulated.</p><button class="primary" data-close="basket"><span>Keep exploring</span><span>→</span></button></div>`;if(!document.querySelector('#basket').open)document.querySelector('#basket').showModal()}
document.addEventListener('click',e=>{const b=e.target.closest('[data-product],[data-cat],[data-mode],[data-close],[data-qty],[data-basket],[data-remove]');if(!b)return;if(b.dataset.product)openItem(b.dataset.product);if(b.dataset.cat){category=b.dataset.cat;render()}if(b.dataset.mode){mode=b.dataset.mode;render()}if(b.dataset.close)document.querySelector('#'+b.dataset.close).close();if(b.dataset.qty){qty=Math.min(20,Math.max(1,qty+Number(b.dataset.qty)));document.querySelector('#qty').textContent=qty;document.querySelector('#total').textContent=money(unit()*qty)}if(b.hasAttribute('data-basket'))basket();if(b.dataset.remove!==undefined){cart.splice(Number(b.dataset.remove),1);basket();updateBasket()}});
document.addEventListener('input',e=>{if(e.target.id==='search'){search=e.target.value;document.querySelector('#menu-results').innerHTML=results()}if(e.target.id==='extra')document.querySelector('#total').textContent=money(unit()*qty)});
document.addEventListener('submit',e=>{if(e.target.id!=='customise')return;e.preventDefault();cart.push({name:selected.name,qty,unit:unit(),choice:new FormData(e.target).get('choice'),extra:document.querySelector('#extra').checked});document.querySelector('#item').close();updateBasket()});
document.querySelector('#account').onclick=()=>{location.hash='account'};window.addEventListener('hashchange',render);render();
